INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1773796225598, 'PnP Cable - 기타수입차 (Other Imported Cars)', 'TY-1A', '토요타 크라운(S230) 23년 이후 JBL 8CH / 케이블길이 15cm', 'A타입 / 차측용 케이블', 150000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/TY-1A.jpg', '[{"id":"1773797145548623665","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/TY-1A-C.jpg"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1773819135551, 'Others', 'Toyota 6.9" 배플', '6.5" 스피커를 토요타 렉서스 차량에 부착할 수 있는 6.9" 배플', '.', 50000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/6.9 배플.jpg', '[{"id":"1773878579079997406","type":"text","value":"알파인 스피커 DM시리즈,S2시리즈 R2시리즈에 알맞습니다.\n\nHDZ스피커 시리즈(알파인 스테이터스),F#1 스피커, DP2시리즈 스피커는 호환되지 않습니다."},{"id":"1773878680471877692","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/6.9 배플-01.jpg"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1773974028877, 'Alpine OEM Fit', 'BYD Sealion7 알파인 사운드 패키지 (무손상 OEM Fit)', '알파인 프리미엄 무손상 PnP 오디오 업그레이드 패키지', '혁신적인 BYD 씰리온7, 사운드의 품격을 완벽하게 높이다!', 2018000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/oem%20fit%20Sealion7.jpg', '[{"id":"1773973769635226865","type":"text","value":"미래지향적인 첨단 전기차 BYD 씰리온7의 정숙한 실내 공간, 그에 걸맞은 하이파이(Hi-Fi) 사운드를 찾고 계신가요?\n\n신차의 순정 배선 훼손 걱정 없이, 가장 안전하고 확실하게 사운드를 업그레이드할 수 있는 알파인의 프리미엄 솔루션을 소개합니다."},{"id":"1773973821772715914","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DSP-R80.jpg"},{"id":"1773973863305156704","type":"text","value":"1. 압도적인 사운드 제어력, 알파인 PXE-R80-8 DSP 앰프\n\n순정 시스템의 답답한 출력과 뭉개지는 해상력을 단번에 해결합니다. 강력한 앰프 출력과 알파인만의 정밀한 DSP 프로세싱 사운드 튜닝 기술이 만나, 씰리온7의 실내 구조에 최적화된 넓고 입체적인 무대감을 완성해 줍니다."},{"id":"1773973887533863009","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/spk-s65c.jpg"},{"id":"1773973903471748350","type":"text","value":"2. 맑고 다이내믹한 프론트 스테이지, 알파인 S2-S65C 컴포넌트 스피커\n\n검증된 성능을 자랑하는 알파인 S2 시리즈 스피커를 전면에 배치했습니다. 선명하고 섬세한 고음역대와 왜곡 없이 단단하게 울려 퍼지는 미드베이스가 결합되어, 주행 중에도 마치 프라이빗 콘서트홀에 있는 듯한 생생한 원음을 재생합니다."},{"id":"1773973924477100243","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/BY-2A-c.jpg"},{"id":"1773973950465896531","type":"text","value":"3. 차량 보증 걱정 제로! 전용 PnP 케이블을 통한 ''100% 무손상'' 인스톨\n\n복잡하게 전선 가닥을 자르거나 이어 붙이는 위험한 개조 작업은 전혀 필요 없습니다. BYD 씰리온7 시스템에 정확히 호환되는 잭-바이-잭(Plug & Play) 전용 케이블을 적용하여 순정 커넥터에 꽂기만 하면 장착이 완료됩니다. 차량 시스템에 어떠한 데미지도 주지 않는 완벽한 무손상 튜닝으로, 신차 무상 보증(Warranty) 혜택까지 안전하게 유지할 수 있습니다."},{"id":"1773973974109196295","type":"text","value":"차원이 다른 알파인 사운드와 완벽한 무손상 인스톨의 결합!\n\n알파인이 자신 있게 선보이는 차별화된 오디오 솔루션으로, BYD 씰리온7과 함께하는 드라이빙의 즐거움을 한 차원 더 높여보세요.\n\n\n장착 문의\n알파인 사운드 마스터\n가인 오디오\n경기도 안양시 만안구 안양로 21\n010-8545-5311"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1774339147421, 'Alpine OEM Fit', 'G80 렉시콘/뱅앤울룹슨_알파인 스테이터스 패키지 (무손상 OEM Fit)', '프리미엄 하이엔드 오디오의 완성! 알파인(ALPINE) 사운드 업그레이드 패키지', '2채널 룸미러 블랙박스 무상 제공', 9144000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi.jpg', '[{"id":"1774338759631571999","type":"text","value":"\"G80의 품격에 걸맞은 사운드를 경험하고 계신가요?\"\n\n제네시스 G80의 순정 렉시콘 오디오, 훌륭하지만 어딘가 아쉬움을 느끼셨나요?\n더 선명한 해상력, 깊고 풍부한 베이스, 눈앞에 펼쳐지는 듯한 라이브 스테이지를 원하시는 오너님들을 위해 준비했습니다.\n\n차량 손상 없이 완벽하게 인스톨되는 알파인(ALPINE) 하이엔드 사운드 패키지로 G80의 실내를 나만의 프리미엄 콘서트홀로 만들어보세요!"},{"id":"1774338776807742563","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/AST-D90.jpg"},{"id":"1774338807905210555","type":"text","value":"1. HDP-D90 | 시스템의 심장, 최고급 14채널 DSP 앰프\n\n알파인 Status(스테이터스) 라인업의 압도적인 기술력이 집약된 하이엔드 DSP 앰프입니다. 렉시콘 시스템의 다채널 스피커를 완벽하게 제어하여 숨겨져 있던 미세한 소리까지 살려내며, 강력한 출력과 정밀한 사운드 튜닝(DSP)으로 운전석에 최적화된 완벽한 사운드 밸런스를 제공합니다."},{"id":"1774338827592088966","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/시공자료실 AST-653S.jpg"},{"id":"1774338882279012161","type":"text","value":"2. HDZ-653S | 프론트 스피커의 혁명, 하이레졸루션 3WAY 스피커\n\n차원이 다른 고해상도(Hi-Res) 오디오를 지원하는 Alpine Status 3WAY 컴포넌트 스피커!\n청명하고 맑은 고음부터 단단하고 타격감 있는 미드베이스까지, 악기 하나하나의 위치와 숨결까지 느껴지는 놀라운 해상력을 선사합니다."},{"id":"1774338895353386446","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/spk-dp265c.jpg"},{"id":"1774338960347953202","type":"text","value":"3. DP2-65C | 공간감을 완성하는 리어 2WAY 스피커\n\n프론트 스피커와 완벽한 음색 조화를 이루는 고품질 2WAY 스피커 세트입니다. 뒷좌석 탑승객은 물론, 실내 전체의 서라운드 입체감과 사운드 스테이지를 한층 더 넓고 깊게 만들어줍니다."},{"id":"1774338992946271442","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DPS-25M-001.jpg"},{"id":"1774339008253032028","type":"text","value":"4. DPS-25M | 보컬의 밀도를 높이는 후석 미드레인지 스피커\n\n사운드의 중심을 꽉 잡아주는 알파인의 고성능 미드레인지입니다. 리어 시트에서 흘러나오는 또렷하고 밀도 있는 사운드로, 눈앞에서 가수가 직접 노래하는 듯한 생생한 센터 이미징을 완성해 줍니다."},{"id":"1774339049729264277","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/GE-2A%20(1).jpg"},{"id":"1774339106966621677","type":"text","value":"5. 100% 무손상 플러그 앤 플레이(PnP) 케이블 적용\n\n\"순정 배선을 잘라야 하나요?\" 절대 아닙니다!\n차량의 순정 배선을 단 1가닥도 자르거나 훼손하지 않는 G80 렉시콘 전용 잭바이잭(PnP) 케이블을 사용합니다. 차량의 제조사 워런티(A/S)에 전혀 지장을 주지 않으며, 언제든 순정 상태로 완벽한 원상복구가 가능합니다.\n\n\n\n🎵 이런 G80 오너님들께 강력 추천합니다!\n✔️ 순정 렉시콘 오디오의 먹먹함과 답답함을 시원하게 해소하고 싶으신 분\n✔️ 차량 디자인과 배선을 100% 유지하면서 사운드만 완벽하게 업그레이드하고 싶으신 분\n✔️ 고음질 음원(Hi-Res)의 디테일과 다이나믹한 감동을 차 안에서 느끼고 싶으신 분\n\n제네시스 G80의 가치를 높이는 가장 확실한 방법.\n세계적인 카오디오 명가, 알파인 프리미엄 오디오 패키지로 당신의 드라이빙에 감동을 더하세요!\n\n\n\n\n\n"},{"id":"1774339190280631899","type":"text","value":"G80 렉시콘/뱅앤울룹슨_알파인 스테이터스 패키지 (무손상 OEM Fit)의 특별 혜택\n\n혜택1) OEM Fit 스피커 패키지 제공"},{"id":"1774396057199635495","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-01.jpg"},{"id":"1774396106633139920","type":"text","value":"좌측 OEM 전면 트위터            \n\n우측 알파인 전면 트위터 패키지\n  - OEM Fit으로 설계된 전면 트위터 배플(스피커 가이드)\n  - HDZ-653S 트위터 스피커\n  - 트위터 라인 패시브 (트위터를 보호하는 장치입니다.)\n  - 유니버셜 스피커 컨넥터 (OEM 스피커 케이블을 절단하거나 탈피하지 않도록 합니다.)"},{"id":"1774396474639987118","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-02.jpg"},{"id":"1774396515245123799","type":"text","value":"전면 트위터 스피커\n좌측 OEM 스피커\n우측 알파인 HDZ-653C"},{"id":"1774396633660822889","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-03.jpg"},{"id":"1774396672250023572","type":"text","value":"좌측 OEM 전면 미드레인지 스피커\n\n우측 알파인 전면 미드레인지 스피커 패키지\n  - OEM Fit으로 설계된 전면 미드레인지 배플(스피커 가이드)\n  - HDZ-653S 미드레인지 스피커\n  - 유니버셜 스피커 컨넥터 (OEM 스피커 케이블을 절단하거나 탈피하지 않도록 합니다.)\n"},{"id":"1774396777738094875","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-04.jpg"},{"id":"1774396841612168204","type":"text","value":"전면 미드레인지 스피커\n좌측 OEM 미드레인지 스피커\n중앙 OEM Fit 배플\n우측 알파인 HDZ-653C"},{"id":"1774396919935095702","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-05.jpg"},{"id":"1774396955959526173","type":"text","value":"좌측 OEM 후면 트위터\n\n우측 알파인 면 트위터 패키지\n- OEM Fit으로 설계된 전면 트위터 배플(스피커 가이드)\n- DP2-65C 트위터 스피커\n- 트위터 라인 패시브 (트위터를 보호하는 장치입니다.)\n- 유니버셜 스피커 컨넥터 (OEM 스피커 케이블을 절단하거나 탈피하지 않도록 합니다.)"},{"id":"1774397034107004038","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-06.jpg"},{"id":"1774397064237810654","type":"text","value":"후면 트위터 스피커\n좌측 OEM 스피커\n우측 알파인 DP2-65C"},{"id":"1774397116494859209","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-07.jpg"},{"id":"1774397156043919800","type":"text","value":"좌측 OEM 후면 미드레인지 스피커\n\n우측 알파인 후면 미드레인지 스피커 패키지\n- OEM Fit으로 설계된 전면 미드레인지 배플(스피커 가이드)\n- DPS-25M 미드레인지 스피커\n- 유니버셜 스피커 컨넥터 (OEM 스피커 케이블을 절단하거나 탈피하지 않도록 합니다.)\n\n"},{"id":"1774397235229871492","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-08.jpg"},{"id":"1774397257763679114","type":"text","value":"후면 미드레인지 스피커\n좌측 OEM 미드레인지 스피커\n중앙 OEM Fit 배플\n우측 알파인 DPS-25M"},{"id":"1774398857637329069","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-09.jpg"},{"id":"1774398872373883182","type":"text","value":"좌측 전면 OEM 미드우퍼\n우측 알파인 HDZ-653S 미드우퍼"},{"id":"1774398909237175285","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/OEM%20fit%20G80%20Lexi-10.jpg"},{"id":"1774398933321745075","type":"text","value":"좌측 후면 OEM 미드우퍼\n우측 알파인 DP2-65C 미드우퍼"},{"id":"1774399025471772353","type":"text","value":"혜택2) 알파인 룸미러 블랙박스 무상 제공"},{"id":"1774399099692634449","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DVR-01.jpg"},{"id":"1774399116517677797","type":"text","value":"알파인 2채널 룸미러 블랙박스\nDVR-DM1000KO-IC\n\n- LCD : 10인치 터치\n- 전면카메라 : Full HD\n- 후면카메라 : Full HD\n- 저장 메모리 : Micro SD\n\n** 제품만 제공해 드리고 장착은 별도의 공임으로 하셔야 합니다."},{"id":"1774399302326726835","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/G80 렉시콘 OEM Fit.jpg"},{"id":"1774400843027220945","type":"text","value":"장착 대리점 안내\n\n아래 링크를 클릭 하시면 전국의 알파인 대리점을 확인 할 수 있습니다.\n\n전화로 문의 해보세요\nhttps://www.alpine-korea.co.kr/pages/dealers.html"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1775014737605, 'Alpine OEM Fit', '[기아 PV5 전용 사운드 튜닝] 알파인 메티오 사운드 패키지 (OEM-Fit)', '"PV5의 넓은 공간, 소리로 가득 채우다. 시판 최초 루프 스피커 적용, 알파인 메티오 시스템."', '"위에서는 맑은 보컬, 아래에서는 묵직한 베이스. PV5만을 위한 입체 사운드의 완성."', 900000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PV5 복사.jpg', '[{"id":"1775014875556575014","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/pv5%20oem%20fit%20-01.jpg"},{"id":"1775014891605631989","type":"text","value":"쏟아지는 사운드, 울려 퍼지는 중저음\n\n박력있는 음악 공간\n\n\n고정 개념을 덮습니다.\n\n시판 최초 루프 스피커 & 도어 우퍼의 조화\n\nPV5 실내를 감싸는 압도적인 사운"},{"id":"1775014993413802785","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/pv5%20oem%20fit%20-02.jpg"},{"id":"1775015014292316227","type":"text","value":"PV5 넓은 실내 공간, 벙벙거리는 순정 오디오가 아쉽다면? 정답은 ''위에서 쏟아지는 사운드''입니다.\n\n차박, 캠핑, 비즈니스까지. 다재다능한 기아 PV5를 출고하셨나요? 공간은 완벽하지만, 음악을 틀어보면 어딘가 답답하고 뭉개지는 소리에 실망하시는 분들이 많습니다. 넓은 층고 때문에 소리가 제대로 전달되지 않기 때문이죠.\n\n**''알파인 메티오 사운드 패키지''**는 발상의 전환을 이뤘습니다.\n천장(루프)에서는 가수의 청아한 목소리가 내려오고, 발밑(도어)에서는 묵직한 베이스가 울려 퍼집니다. 마치 콘서트홀 VIP석에 앉아있는 듯한 완벽한 공간감을 PV5 안에서 누려보세요.\n\n복잡한 개조? 걱정하지 마세요. PV5 전용 가이드가 포함된 OEM-Fit으로 내 차에 상처 하나 없이 단 90만 원에 프리미엄 사운드를 완성할 수 있습니다."},{"id":"1775015071905184153","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PV5 복사.jpg"},{"id":"1775015193089201392","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/pv5%20oem%20fit%20-03.jpg"},{"id":"1775015193857254285","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/pv5%20oem%20fit%20-04.jpg"},{"id":"1775015194353563120","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/pv5%20oem%20fit%20-05.jpg"},{"id":"1775015194745872205","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PV5%20Baffle.jpg"},{"id":"1775015266966584437","type":"text","value":"PV5는 5.25\" OEM 스피커로 구성되어 있어서 6.5\" 스피커로 교체하려면 커스텀 가이드를 사용해야 합니다."},{"id":"1775093341688908358","type":"text","value":"Q. 기아 PV5 오디오 튜닝, 왜 알파인 메티오 사운드 패키지여야 할까요?\n\n실내 공간이 넓은 PBV(목적 기반 모빌리티) 차량의 특성상, 일반적인 스피커 교체만으로는 소리가 비어 보이거나 흩어지기 쉽습니다. 알파인 메티오 사운드 패키지는 PV5의 실내 구조를 완벽히 분석하여 설계된 전용 맞춤형(OEM-Fit) 카오디오 시스템입니다.\n\n✓ 시판 최초 루프 & 도어 스피커 분리 설계\n천장에 설치되는 루프 스피커에서 맑고 선명한 중고역대(보컬) 사운드가 쏟아지고, 도어 우퍼에서 깊고 탄탄한 저음이 베이스를 잡아주어 실내 전체를 감싸는 압도적인 3D 입체 음향을 완성합니다.\n\n✓ 완벽한 OEM-Fit, 차량 손상 ZERO\n기아 PV5 전용 스피커 배플(가이드)을 기본 제공하여, 순정 배선이나 도어 프레임의 훼손 없이 깔끔하고 완벽한 인스톨이 가능합니다."}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1775457031776, 'PnP Cable - 독일차 (German Cars)', 'BM-4A', 'BMW 구형 자출 4채널', 'A 타입 차측용 / 1.5M', 230000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/BM-404.jpg', '[{"id":"1775457019006827690","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/BM-404-C.jpg"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1775457981007, 'Others', '트위터 라인 패시브', '400V 4.7uf', '', 8000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/트위터 라인패시브.jpg', '[{"id":"1775457767810341445","type":"text","value":"트위터 보호를 위한 하이패스 필터입니다.\n\n4Ω 기준 8.4hHz 컷오프 입니다.\n\n제네시스나 현대 기아차의 트위터가 미드레인지나 미드우퍼에 패시브로 연결되었을 경우 Alpine Status 653S나 DP2-653의 트위터 보호할때 장착 합니다.\n\n\n사이즈 : 두께 2CM, 길이 3.5CM"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1775458959969, 'Others', '미드레인지 라인 패시브', '400V 47uf', '', 25000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/미드레인지 라인 패시브.jpg', '[{"id":"1775458293574544624","type":"text","value":"미드레인지 보호를 위한 하이패스 필터 입니다.\n\n4Ω기준 846Hz 컷오프\n\nK8과 같이 미드레인지와 미드우퍼가 패시브 상태일경우 HDZ-653S나 DP2-653의 미드레인지 스피커를 보호할때 사용합니다.\n\n\n사이즈 : 두께 3.3CM  길이 5.5CM"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1776135277967, 'Alpine OEM Fit', '[기아 PV5 전용 사운드 튜닝] 알파인 사운드 패키지(OEM-Fit)', '순정 그대로, 사운드만 업그레이드하세요. PV5 전용 알파인 사운드 패키지 출시', '이동의 순간이 즐거움이 되는 시간, PV5 with Alpine', 1700000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PV5 알파인 패키지 복사-01.jpg', '[{"id":"1776135124972278336","type":"text","value":"\"비즈니스와 라이프스타일의 경계를 허무는 압도적 해상력, PV5 전용 알파인 솔루션\"\n기아 PV5는 단순한 이동 수단을 넘어 비즈니스, 딜리버리, 라이프스타일을 아우르는 혁신적인 목적 기반 차량(PBV)입니다. 하지만 다양한 공간 활용성에 비해 기본 사운드 시스템은 광활한 실내를 채우기에 다소 아쉬움이 남습니다.\n\n알파인이 제안하는 이번 패키지는 PV5의 다목적 공간을 완벽한 리스닝 룸으로 변화시킵니다. 업무 중에는 차분한 휴식을, 이동 중에는 활기찬 에너지를 선사하는 하이엔드 사운드를 경험해 보십시오."},{"id":"1776135151208458602","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DSP-M60.jpg"},{"id":"1776135152080900601","type":"text","value":"1. 사운드의 두뇌: Alpine PXE-M60-4 (DSP Amp)\n\"PV5의 독특한 실내 구조를 완벽하게 제어하는 스마트 지휘자\"\n\n이번 패키지의 핵심은 정밀한 사운드 설계가 가능한 DSP 앰프 PXE-M60-4입니다. 단순히 출력만 높이는 것이 아니라 PV5의 넓은 공간감을 최적화합니다.\n\n정밀 튜닝(Time Alignment): PV5의 시트 위치에 상관없이 소리가 도달하는 시간을 정밀하게 조정하여, 대시보드 위로 무대가 펼쳐지는 듯한 ''사운드 스테이징''을 구현합니다.\n\n컴팩트 & 파워풀: 시트 하단이나 보이지 않는 곳에 매립 가능한 콤팩트한 사이즈임에도 불구하고, 순정과는 비교할 수 없는 단단하고 풍성한 출력을 제공합니다."},{"id":"1776135186784017312","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/spk-dm65c.jpg"},{"id":"1776135187408504929","type":"text","value":"2. 소리의 기준: Alpine DM-65C (Component Speaker)\n\"왜곡 없는 깨끗함, 보컬의 디테일까지 살려내는 고해상도 사운드\"\n\n프론트 도어에 장착되는 DM-65C는 알파인의 기술력이 담긴 고성능 스피커로, 소리의 명료도를 극적으로 향상시킵니다.\n\n맑은 고음과 탄탄한 중음: 순정 스피커의 답답함을 벗겨내고, 고음 트위터와 미드우퍼의 조화를 통해 악기 하나하나의 결을 선명하게 살려냅니다.\n\n고내구성 설계: 다양한 환경에서 운행되는 PV5의 특성에 맞춰 일관된 성능을 발휘하도록 설계되었습니다."},{"id":"1776135200450153841","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/amp-m770-0.jpg"},{"id":"1776135200970911337","type":"text","value":"3. 저음의 완성: Alpine PWE-M770 (Compact Subwoofer)\n\"공간을 가득 채우는 깊고 풍부한 베이스의 감동\"\n\n초소형 파워 우퍼 PWE-M770은 PV5의 실내 공간을 해치지 않으면서 가슴을 울리는 타격감을 더합니다.\n\n초슬림 다이캐스트 바디: PV5의 효율적인 공간 활용을 방해하지 않으며 시트 하단 등에 완벽하게 안착됩니다.\n\n밀도 높은 저역대: 7인치 서브우퍼가 뿜어내는 깊고 묵직한 베이스는 음악의 몰입감을 한층 더 깊게 만듭니다."},{"id":"1776135217330369929","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/HK-104.jpg"},{"id":"1776135217778312615","type":"text","value":"[PV5 전용 무손상 솔루션: Non-Destructive Solution]\n\"차량 손상 0%, 사운드 만족도 100% — 전용 PnP 케이블로 완성하는 완벽한 핏\"\n\n고객님의 소중한 신차 PV5에 단 하나의 배선 손상도 허용하지 않습니다. JCH Auto는 전용 PnP(Plug & Play) 케이블 방식을 사용하여 순정 가치를 그대로 유지합니다.\n\n1. 배선 절단 없는 ''Jack by Jack'' 인스톨\n순정 배선을 자르거나 피복을 벗기지 않습니다. PV5 전용 하네스를 사용하여 잭을 맞물려 연결하는 방식으로, 전기적 오류를 방지하고 순정 시스템과 완벽하게 동기화됩니다.\n\n2. 제조사 워런티 걱정 제로\n차량 내부의 배선 구조를 전혀 변경하지 않으므로, 공식 서비스 센터 방문 시 배선 개조로 인한 보증 수리 거부 우려가 없습니다. 필요 시 언제든 100% 순정 상태로 복구가 가능합니다.\n\n3. 노이즈 프리(Noise-Free) 설계\n수작업 배선 연결에서 발생할 수 있는 접촉 불량이나 노이즈 유입을 차단합니다. 전용 쉴드 케이블을 통해 깨끗하고 안정적인 신호 전달을 보장합니다."},{"id":"1776140288542307344","type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/PV5%20Baffle.jpg"},{"id":"1776140309012417533","type":"text","value":"PV5는 5.25\" OEM 스피커로 구성되어 있어서 6.5\" 스피커로 교체하려면 커스텀 가이드를 사용해야 합니다.\n\n\n\n알파인이 감동의 사운드를 완성합니다.\n지금 전국 알파인 공식 대리점에서 PV5 전용 패키지를 만나보십시오.\n\n[장착 대리점 안내 링크]\nhttps://www.alpine-korea.co.kr/pages/dealers.html"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;